from collections import Counter, deque


def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    cells = {(r, c) for r in range(h) for c in range(w) if g[r][c] != bg}

    # Find connected non-background objects; the largest is the stamp/template.
    comps = []
    unseen = set(cells)
    while unseen:
        start = unseen.pop()
        comp = {start}
        q = [start]
        while q:
            r, c = q.pop()
            for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    q.append(p)
        comps.append(comp)
    template = max(comps, key=len)
    tr0 = min(r for r, c in template); tr1 = max(r for r, c in template)
    tc0 = min(c for r, c in template); tc1 = max(c for r, c in template)
    ar, ac = (tr0 + tr1)//2, (tc0 + tc1)//2
    stamp = [(r-ar, c-ac, g[r][c]) for r,c in template]

    markers = [p for comp in comps if comp is not template for p in comp]
    # The template is in the original grid; other isolated foreground cells mark copies.
    for r,c in markers:
        g[r][c] = bg
    for r,c in markers:
        for dr,dc,color in stamp:
            rr,cc = r+dr,c+dc
            if 0 <= rr < h and 0 <= cc < w:
                g[rr][cc] = color
    return g

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Mark complete monochrome rows and columns with color 2.
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]):
            out[r] = [2] * w
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            for r in range(h):
                out[r][c] = 2
    return out

