def transform(grid):
    # Candidate expansion: preserve source in the upper-left, and fill other
    # panels with permutations of its cells using deterministic index shifts.
    n, m = len(grid), len(grid[0])
    cells = [v for row in grid for v in row]
    panels = []
    for shift in (1, 5, 9):
        a = cells[shift:] + cells[:shift]
        panels.append([a[r*m:(r+1)*m] for r in range(n)])
    out = []
    for r in range(n): out.append(list(grid[r]) + panels[0][r])
    for r in range(n): out.append(panels[1][r] + panels[2][r])
    return out

def transform(grid):
    # Draw diagonal 1s between existing 1 cells when they lie on one diagonal.
    out = [row[:] for row in grid]
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    if len(ones) >= 2:
        (r1, c1), (r2, c2) = ones[:2]
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        if abs(r2-r1) == abs(c2-c1):
            for k in range(1, abs(r2-r1)):
                out[r1 + dr*k][c1 + dc*k] = 1
    return out

