def transform(grid):
    from collections import Counter
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    connected_lines = []
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if r1 != r2 and abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                slope = dr * dc
                connected_lines.append((r1, c1, slope))
                for k in range(1, abs(r2-r1)):
                    if grid[r1+dr*k][c1+dc*k] == bg:
                        out[r1+dr*k][c1+dc*k] = 1
    # A 6 extends along the perpendicular diagonal only when on a line joining 1s.
    for r, c in sixes:
        for r1, c1, slope in connected_lines:
            if (r-r1) * slope == c-c1:
                diag = -slope
                for step in (-1, 1):
                    rr, cc = r+step, c+step*diag
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] == bg:
                            out[rr][cc] = 6
                        rr += step
                        cc += step*diag
                break
    return out

