def transform(grid):
    h,w=len(grid),len(grid[0])
    # Find the two vertical T orientations by their complete 2x3 pattern.
    shapes=[]
    for r in range(h-1):
        for c in range(w-2):
            top=grid[r][c:c+3]
            bot=grid[r+1][c:c+3]
            if top==[0,2,0] and bot==[2,2,2]:
                shapes.append((r,c,3))  # stem above the bar
            elif top==[2,2,2] and bot==[0,2,0]:
                shapes.append((r,c,1))  # stem below the bar
    # Demos establish a 3x6 signature. Two vertical bands occupy rows 0 and 2;
    # order shapes left-to-right within each band, preserving the orientation code.
    out=[[0]*6 for _ in range(3)]
    bands=[[],[]]
    for r,c,color in shapes:
        band=0 if r < h/2 else 1
        bands[band].append((c,color))
    for band,items in enumerate(bands):
        items.sort()
        slots=([0,2,3] if len(items)>=3 else [0,2])
        for (c,color),col in zip(items,slots):
            out[0 if band==0 else 2][col]=color
    return out

