def transform(grid):
    """Paired edge bars project lanes; a marker intercepting one lane is relayed."""
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    counts = {v: sum(row.count(v) for row in src) for v in {x for row in src for x in row}}
    bg = max(counts, key=counts.get)

    # Locate monochrome non-background runs on each edge.
    runs = []
    for side, line in [('top', src[0]), ('bottom', src[-1])]:
        i = 0
        while i < w:
            if line[i] == bg:
                i += 1
                continue
            col, j = line[i], i + 1
            while j < w and line[j] == col:
                j += 1
            runs.append((side, col, i, j))
            i = j
    for side, c in [('left', 0), ('right', w - 1)]:
        i = 0
        while i < h:
            if src[i][c] == bg:
                i += 1
                continue
            col, j = src[i][c], i + 1
            while j < h and src[j][c] == col:
                j += 1
            runs.append((side, col, i, j))
            i = j

    pairs = []
    for a, b in [('top', 'bottom'), ('left', 'right')]:
        A = [r for r in runs if r[0] == a]
        B = [r for r in runs if r[0] == b]
        for x in A:
            for y in B:
                if x[1] == y[1] and x[3] - x[2] == y[3] - y[2]:
                    pairs.append((x, y))

    def coords(edge, offset):
        side, color, start, end = edge
        pos = start + offset
        if side == 'top': return [(r, pos) for r in range(1, h-1)]
        if side == 'bottom': return [(r, pos) for r in range(h-2, 0, -1)]
        if side == 'left': return [(pos, c) for c in range(1, w-1)]
        return [(pos, c) for c in range(w-2, 0, -1)]

    for e1, e2 in pairs:
        for offset in range(e1[3] - e1[2]):
            for own, mate in ((e1, e2), (e2, e1)):
                line = coords(own, offset)
                marker = None
                for p in line:
                    r, c = p
                    if src[r][c] != bg:
                        if src[r][c] != own[1]:
                            marker = p
                        break
                if marker is None:
                    continue
                mr, mc = marker
                mark_color = src[mr][mc]
                # Fill from this bar up to the intercepted marker, then recolor it.
                for r, c in line:
                    if (r, c) == marker:
                        break
                    if src[r][c] == bg:
                        out[r][c] = mark_color
                out[mr][mc] = 4
                # Relay the marker color along the corresponding lane at the mate bar.
                for r, c in coords(mate, offset):
                    if src[r][c] == bg:
                        out[r][c] = mark_color
    return out

